conf:
server {
listen 8080;
server_name _;
root /usr/share/nginx/html;
index index.html;
add_header X-Frame-Options "DENY" always;
add_header Content-Security-Policy "default-src 'self'; script-src 'self'; style-src 'self' 'unsafe-inline'; font-src 'self' data:; img-src 'self' data: https:; connect-src 'self' http://wallet.stock.giano.localhost http://wallet.byo.giano.localhost http://rpc.giano.localhost http://rpc-b.giano.localhost; frame-ancestors 'none'; base-uri 'self'; form-action 'self'" always;
add_header X-Content-Type-Options "nosniff" always;
add_header Referrer-Policy "no-referrer" always;
location = /config.js {
add_header Cache-Control "no-store" always;
add_header X-Frame-Options "DENY" always;
add_header Content-Security-Policy "default-src 'self'; script-src 'self'; style-src 'self' 'unsafe-inline'; font-src 'self' data:; img-src 'self' data: https:; connect-src 'self' http://wallet.stock.giano.localhost http://wallet.byo.giano.localhost http://rpc.giano.localhost http://rpc-b.giano.localhost; frame-ancestors 'none'; base-uri 'self'; form-action 'self'" always;
add_header X-Content-Type-Options "nosniff" always;
add_header Referrer-Policy "no-referrer" always;
}
location /assets/ {
add_header Cache-Control "public, max-age=31536000, immutable" always;
add_header X-Frame-Options "DENY" always;
add_header Content-Security-Policy "default-src 'self'; script-src 'self'; style-src 'self' 'unsafe-inline'; font-src 'self' data:; img-src 'self' data: https:; connect-src 'self' http://wallet.stock.giano.localhost http://wallet.byo.giano.localhost http://rpc.giano.localhost http://rpc-b.giano.localhost; frame-ancestors 'none'; base-uri 'self'; form-action 'self'" always;
add_header X-Content-Type-Options "nosniff" always;
add_header Referrer-Policy "no-referrer" always;
}
location / {
expires epoch;
add_header Cache-Control "no-cache" always;
add_header X-Frame-Options "DENY" always;
add_header Content-Security-Policy "default-src 'self'; script-src 'self'; style-src 'self' 'unsafe-inline'; font-src 'self' data:; img-src 'self' data: https:; connect-src 'self' http://wallet.stock.giano.localhost http://wallet.byo.giano.localhost http://rpc.giano.localhost http://rpc-b.giano.localhost; frame-ancestors 'none'; base-uri 'self'; form-action 'self'" always;
add_header X-Content-Type-Options "nosniff" always;
add_header Referrer-Policy "no-referrer" always;
try_files $uri $uri/ /index.html;
}
}
